          const s=String(arr[i]?.mes||arr[i]?.message||arr[i]?.content||"");
          let m=s.match(/(20\d{2})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日(?:[\s\S]{0,30}?(\d{1,2})\s*[:：]\s*(\d{2}))?/);
          if(m)return `${m[1]}年${String(+m[2]).padStart(2,"0")}月${String(+m[3]).padStart(2,"0")}日${m[4]!=null?` ${String(+m[4]).padStart(2,"0")}:${m[5]}`:""}`;
          m=s.match(/(20\d{2})[-/.](\d{1,2})[-/.](\d{1,2})(?:[ T](\d{1,2})[:：](\d{2}))?/);
          if(m)return `${m[1]}年${String(+m[2]).padStart(2,"0")}月${String(+m[3]).padStart(2,"0")}日${m[4]!=null?` ${String(+m[4]).padStart(2,"0")}:${m[5]}`:""}`;
