    async function runPhoneRaw(systemText,userInput,maxHistory=8){
      const preparedScope=actionScope();
      if(features)await features.scanLore(false);
      if(preparedScope!==actionScope())throw new Error("剧情在准备请求时发生变化，本次请求未发出");
      const loreContext=features?.contextText(systemText+"\n"+userInput,false)||"";
      if(loreContext)systemText+=`\n【资料分层；当前正文优先，不是人物的共享知识】\n${loreContext}`;
      const native=nativeStRawFn();
      if(native){
        const ctx=compactPhoneContext();
        const prompt=[
          ctx,
          `当前剧情时间：${storyTime()}`,
          `任务：${userInput}`,
          "严格遵守系统要求，只返回任务要求的结果。"
        ].filter(Boolean).join("\n\n");
        const raw=await native({systemPrompt:systemText,prompt});
        if(!String(typeof raw==="string"?raw:(raw?.content||"")).trim())throw new Error("native generateRaw returned empty result");
        return {raw,source:"native"};
      }
      const legacy=tavernHelperGenFn();
      if(!legacy)throw new Error("no supported phone generation API");
      const raw=await runPhoneLegacyRaw(systemText,userInput,maxHistory);
      return {raw,source:"legacy"};
    }
    function cleanRaw(r){
      let t=typeof r==="string"?r:(r?.content||"");
      return String(t||"").replace(/^```(?:json|text|markdown)?\s*/i,"").replace(/```\s*$/,"").trim();
    }
