        if(requestScope!==actionScope())throw new Error("聊天已切换，本次请求已取消");
        const enforcedSystem=`${SOURCE_POLICY}\n${systemText}\n${PHONE_RELEVANCE_LOCK}\n${options.anonymous?"【树洞补充】NPC匿名投稿可以负面、毒舌、抱怨、粗口；不强行改成夸赞、道歉或自我审查，不建立作者映射，不安排追查身份与报复。":WORD_BAN}`;
        const packet=await runPhoneRaw(enforcedSystem,userInput,8);
