    function dedupeSocialComments(arr,limit=20){
      const out=[],seen=new Set();
      for(const c of (Array.isArray(arr)?arr:[])){
        if(!c||!String(c.text||"").trim())continue;
        const key=`${String(c.author||"").trim()}|${String(c.replyTo||"").trim()}|${String(c.text||"").trim()}`;
        if(seen.has(key))continue;
        seen.add(key);out.push(c);
      }
      return out.slice(-limit);
    }
    function dedupeMomentList(arr){
      const out=[],seen=new Set();
      for(const p of (Array.isArray(arr)?arr:[])){
        if(!p)continue;
        const key=`${String(p.author||"").trim()}|${String(p.time||"").trim()}|${String(p.text||"").trim()}`;
        if(seen.has(key))continue;
        seen.add(key);
        p.comments=dedupeSocialComments(p.comments,20);
        out.push(p);
      }
      return out;
    }

