    function collectPhoneOlder(st){
      st=normalizeState(st);
      const out=[];let count=0;
      for(const [name,arr0] of Object.entries(st.wechat.threads||{})){
        const arr=Array.isArray(arr0)?arr0:[];
        for(const m of arr.slice(0,Math.max(0,arr.length-6))){
          if(m?.kind==="image")continue; // legacy media is ignored; never turn it into a text substitute
          count++;
          out.push(`[微信/${name}] ${m?.time||""} ${m?.from==="user"?getUserName():name}：${String(m?.text||"").slice(0,300)}`);
        }
      }
      const moments=(Array.isArray(st.wechat.moments)?st.wechat.moments:[]).filter(p=>normalizeVisibility(p.visibility).mode==="all").filter(hasUserMomentInteraction);
      for(const p of moments.slice(0,Math.max(0,moments.length-4))){
        count++;out.push(`[朋友圈] ${p?.time||""} ${p?.author||""}：${String(p?.text||"").slice(0,320)}`);
      }
      for(const p of moments.slice(-4)){
        const cs=Array.isArray(p?.comments)?p.comments:[];
        for(const c of cs.slice(0,Math.max(0,cs.length-4))){
          count++;out.push(`[朋友圈评论] ${c?.time||p?.time||""} ${c?.author||""}：${String(c?.text||"").slice(0,220)}`);
        }
      }
      for(const key of ["feed","myPosts"]){
        const base=Array.isArray(st.weibo[key])?st.weibo[key]:[];
        const arr=key==="feed"?base.filter(hasUserWeiboInteraction):base;
        for(const p of arr.slice(0,Math.max(0,arr.length-4))){
          count++;out.push(`[微博${key==="myPosts"?"/用户发帖":"/动态"}] ${p?.time||""} ${p?.author||""}：${String(p?.text||"").slice(0,320)}`);
        }
        for(const p of arr.slice(-4)){
          const cs=Array.isArray(p?.comments)?p.comments:[];
          for(const c of cs.slice(0,Math.max(0,cs.length-4))){
            count++;out.push(`[微博评论] ${c?.time||p?.time||""} ${c?.author||""}：${String(c?.text||"").slice(0,220)}`);
          }
        }
      }
      return {count,text:out.join("\n").slice(-14000)};
    }
