    async function imageFileToWallpaper(file){
      if(!file)return "";
      const raw=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(String(fr.result||""));fr.onerror=reject;fr.readAsDataURL(file);});
      return await new Promise((resolve)=>{
        const im=new Image();
        im.onload=()=>{
          const maxW=900,maxH=1800,ratio=Math.min(1,maxW/im.width,maxH/im.height);
          const w=Math.max(1,Math.round(im.width*ratio)),h=Math.max(1,Math.round(im.height*ratio));
          const cv=pdoc.createElement("canvas");cv.width=w;cv.height=h;
          const g=cv.getContext("2d");g.drawImage(im,0,0,w,h);
          try{resolve(cv.toDataURL("image/jpeg",.84));}catch(_){resolve(raw);}
        };
        im.onerror=()=>resolve(raw);im.src=raw;
      });
    }
