      if(vv){
        return {
          left:Number.isFinite(vv.offsetLeft)?vv.offsetLeft:0,
          top:Number.isFinite(vv.offsetTop)?vv.offsetTop:0,
          width:Number.isFinite(vv.width)&&vv.width>0?vv.width:pwin.innerWidth,
          height:Number.isFinite(vv.height)&&vv.height>0?vv.height:pwin.innerHeight,
          scale:Number.isFinite(vv.scale)&&vv.scale>0?vv.scale:1
        };
      }
      return {left:0,top:0,width:pwin.innerWidth,height:pwin.innerHeight,scale:1};
