        const packet=transferStoryPacket(arr,Math.max(0,start-4));if(!packet.length)return false;
        const sys=`你只负责审计一段现代剧情中【当前user与当前character之间已经实际完成的钱款移动】。不要靠“借/还”单个关键词下结论，要看完整上下文与动作是否真的完成。
当前user：${getUserName()}；当前character：${w.char?.name||getCharName()}。
硬规则：
1. 只有钱已经实际从一方到另一方账户/手中，才算completed=true。例如正文明确显示转账金额被输入并发送、转账气泡/收款界面已经形成、到账/收到款、现金已经交付。仅仅“想借、开口要钱、答应给、准备转、输入金额但没有完成动作”都不算。
2. completed后根据前后语境判定type：loan=借款（以后要还）；repay=偿还既有欠款；gift=赠与/明确不用还；payment=消费/付款/其他交易。不要把礼物、买单、工资、普通消费付款记成借款。
3. 对loan：sender是出借人，receiver是借款人；对repay：sender是还钱的借款人，receiver是债权人。
4. 如果一笔真实转账的同一消息没有再写“借”，但前文已经明确双方是在借钱，这仍然是loan。
5. 不要处理股票、财富App打工工资；这里只审计剧情正文里双方实际转给对方的钱。
6. message_index必须填【最终完成转账/到账】所在消息的索引。
只输出JSON：{"events":[{"message_index":123,"completed":true,"type":"loan|repay|gift|payment","sender":"user|char","receiver":"user|char","amount":10000,"reason":"一句简短依据"}]}。没有已完成交易就events为空。`;
        let out;try{out=await askWealthJson(sys,JSON.stringify({messages:packet}));}catch(e){console.warn("[蝴蝶小手机 v1.5.1] 实际转账语义审计失败，稍后会重试",e);return false;}
        w=getWealthState();let changed=false;for(const ev of (Array.isArray(out?.events)?out.events:[])){
          if(ev?.completed!==true)continue;const mi=Math.round(Number(ev?.message_index));if(!Number.isInteger(mi)||mi<0||mi>=arr.length)continue;
          const type=String(ev?.type||"");if(!["loan","repay","gift","payment"].includes(type))continue;
          const sender=ev?.sender==="char"?"char":ev?.sender==="user"?"user":"",receiver=ev?.receiver==="char"?"char":ev?.receiver==="user"?"user":"",amount=wealthMoney(ev?.amount);if(!sender||!receiver||sender===receiver||amount<=0)continue;
          const mh=storyMessageHash(arr[mi],mi),eventId=`semantic-transfer|${mh}|${type}|${sender}|${receiver}|${amount}`;if(loanEventSeen(w,eventId))continue;
          const eventDay=storyDayAtMessage(arr,mi,day),eventTime=storyTimeAtMessage(arr,mi,eventDay);
          const note=`${String(ev?.reason||"").slice(0,110)}｜${cleanTransferStoryText(arr[mi]).slice(0,120)}`;
          if(type==="loan"){if(addLoan(w,sender,receiver,amount,eventDay,eventId,"semantic-transfer",note,eventTime,mi))changed=true;}
          else if(type==="repay"){if(repayLoan(w,sender,receiver,amount,eventDay,eventId,"semantic-transfer",note,eventTime,null,mi))changed=true;}
        }
        for(const h of newHashes)processed.add(h);w.processedTransferStory=Array.from(processed).slice(-420);w.transferParserVersion=2;if(changed)rebuildDebtLedgerFromRoots(w,arr);if(changed||upgrade||hasNew)saveWealthState(w);return changed;
