    function escRe(s){return String(s||"").replace(/[.*+?^${}()|[\]\\]/g,"\\$&");}
    function cnNumber(s){
      s=String(s||"").trim();if(/^\d+$/.test(s))return Math.max(0,parseInt(s,10));
      const map={零:0,一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9};let total=0,cur=0;
      for(const ch of s){if(map[ch]!=null)cur=map[ch];else if(ch==="十"){total+=(cur||1)*10;cur=0;}else if(ch==="百"){total+=(cur||1)*100;cur=0;}}
      return total+cur;
    }
    function detectWorkDays(sentence){
      const s=String(sentence||"");const n="([0-9一二两三四五六七八九十百]+)";
      const pats=[
        new RegExp(`${n}\\s*(?:天|日)[^。！？\n]{0,32}(?:打工|兼职|上班|工作|工(?:作)?|店员|服务员|照顾|喂养)`),
        new RegExp(`(?:打工|兼职|上班|工作|干了?|做了?|打了?)[^。！？\n]{0,26}${n}\\s*(?:天|日)`),
        new RegExp(`(?:打了?|干了?)\\s*${n}\\s*(?:天|日)\\s*(?:的)?\\s*(?:工|班|兼职)`)
      ];
      for(const p of pats){const m=s.match(p);if(m){const raw=m.slice(1).find(x=>x&&/[0-9一二两三四五六七八九十百]+/.test(x));const x=cnNumber(raw);if(x>0)return Math.min(x,3660);}}
      if(/(?:今天|当天|一天)/.test(s))return 1;
      return 1;
    }
    function detectJob(sentence){return WEALTH_JOBS.find(j=>j.re.test(String(sentence||"")))||null;}
    function workIntent(sentence){return /打工|兼职|上班|工作|干了?|值班|上了?\s*班|打了?[^。！？\n]{0,24}(?:天|日)?[^。！？\n]{0,10}(?:工|班)|做了?[^。！？\n]{0,10}(?:店员|服务员)|当了?[^。！？\n]{0,10}(?:店员|服务员)|照顾(?:了)?(?:流浪)?猫|喂养(?:了)?(?:流浪)?猫/.test(String(sentence||""));}
