      try{const o=await askWealthJson(sys,ctx);const tier=["normal","comfortable","wealthy"].includes(o?.tier)?o.tier:"normal";const risk=["low","medium","high"].includes(o?.risk)?o.risk:"medium";const names=Array.isArray(o?.stocks)?o.stocks.map(x=>String(x||"").replace(/[<>]/g,"").trim()).filter(Boolean).slice(0,4):[];return {tier,risk,stocks:names.length===4?names:WEALTH_FALLBACK_STOCKS};}
      catch(e){console.warn("[蝴蝶小手机 v1.5.1] 财富档案推断失败，使用默认档",e);return {tier:"normal",risk:"medium",stocks:WEALTH_FALLBACK_STOCKS};}
