      const upnl=Math.max(-userStake,Math.round(userStake*returns[userStockId]/100));let uDebtPaid=0,uNetChange=upnl;if(upnl>0){const income=applyEarnedIncome(w,"user",upnl,day,`trade-user-${day.key}`,"stock-profit","股票已实现盈利");uDebtPaid=income.debtPaid;uNetChange=income.netAdded;}else{w.user.balance=wealthMoney(w.user.balance+upnl);}w.trades.push({id:`trade-user-${day.key}`,order:nextWealthOrder(w),actor:"user",dayKey:day.key,time:storyTime(),stockId:userStockId,stockName:us.name,stake:userStake,change:returns[userStockId],pnl:upnl,debtPaid:uDebtPaid,netAssetChange:uNetChange,balanceAfter:w.user.balance,source:"random-program"});autoBankruptcyIfZero(w,"user");
