    function campusStoryContext(limit=14){
      try{
        const arr=storyMessages(),start=Math.max(0,arr.length-limit);
        return arr.slice(start).map((m,j)=>{
          const i=start+j,isUser=m?.is_user===true||m?.role==="user";
          const raw=String(m?.mes||m?.message||m?.content||"").replace(/<!--[\s\S]*?-->/g," ").replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim().slice(0,850);
          return raw?`[消息索引 ${i}｜${isUser?"user":"char"}｜来源键 ${storyMessageHash(m,i)}] ${raw}`:"";
        }).filter(Boolean).join("\n");
      }catch(_){return "";}
    }
    function campusSourceKeys(indices){
      try{
        const arr=storyMessages();return campusStrings(indices,12).map(Number).filter(i=>Number.isInteger(i)&&i>=0&&i<arr.length).map(i=>storyMessageHash(arr[i],i));
      }catch(_){return [];}
    }
