          if(!title||campusHasClubText(title,description,organizer))continue;const start=parseStoryDate(String(row?.start_day||""))?.key,end=parseStoryDate(String(row?.end_day||row?.start_day||""))?.key;if(!start||!end)continue;
          const sv=campusDayValue(start),ev=campusDayValue(end);if(sv==null||ev==null||ev<sv||ev<now)continue;const sig=`${title}|${start}`;if(seen.has(sig)||c.events.some(e=>e.title===title&&e.historyLocked))continue;seen.add(sig);
