          const sourceStoryKeys=campusSourceKeys(row?.source_message_indices),event=normalizeCampusEvent({id:makeId("campus-event"),title,type:String(row?.type||"校园活动"),description,location:String(row?.location||""),organizer,startDay:start,endDay:end,deadlineDay:deadline,cancelled:false,historyLocked:false,source:"generated",sourceStoryKeys,charStatus:["attending","not_attending","unknown"].includes(row?.char_status)?row.char_status:"unknown",charReason:String(row?.char_reason||""),order:nextCampusOrder(c)});c.events.push(event);
