    function syncCampusFromStory(){
      const c=getCampusState();if(c.setupStatus==="empty"&&!c.posts.length&&!c.events.length&&!c.registrations.length)return false;
      try{
        const arr=storyMessages(),keys=new Set(arr.map((m,i)=>storyMessageHash(m,i))),alive=x=>!Array.isArray(x?.sourceStoryKeys)||!x.sourceStoryKeys.length||x.sourceStoryKeys.every(k=>keys.has(k));
        const before=JSON.stringify({posts:c.posts.map(x=>x.id),comments:c.posts.flatMap(p=>p.comments.map(q=>q.id)),events:c.events.map(x=>[x.id,x.historyLocked]),regs:c.registrations.map(x=>x.id),notes:c.notifications.map(x=>x.id),actions:c.userActions.map(x=>x.id)});
        const removedPostIds=new Set(c.posts.filter(p=>!alive(p)).map(p=>p.id)),removedCommentIds=new Set(c.posts.filter(p=>removedPostIds.has(p.id)).flatMap(p=>p.comments.map(q=>q.id)));c.posts=c.posts.filter(alive);
        for(const p of c.posts){for(const q of p.comments){if(!alive(q))removedCommentIds.add(q.id);}}
        let cascade=true;while(cascade){cascade=false;for(const p of c.posts){for(const q of p.comments){if(q.triggerRefId&&removedCommentIds.has(q.triggerRefId)&&!removedCommentIds.has(q.id)){removedCommentIds.add(q.id);cascade=true;}}}}
        for(const p of c.posts)p.comments=p.comments.filter(q=>!removedCommentIds.has(q.id));
        const removedEventIds=new Set(c.events.filter(e=>!alive(e)).map(e=>e.id));c.events=c.events.filter(alive);const eventIds=new Set(c.events.map(e=>e.id));
        c.registrations=c.registrations.filter(r=>alive(r)&&eventIds.has(r.eventId));c.notifications=c.notifications.filter(n=>(!n.postId||!removedPostIds.has(n.postId))&&(!n.commentId||!removedCommentIds.has(n.commentId))&&(!n.triggerRefId||!removedCommentIds.has(n.triggerRefId))&&(!n.eventId||eventIds.has(n.eventId)));
        c.userActions=c.userActions.filter(a=>!removedPostIds.has(a.refId)&&!removedCommentIds.has(a.refId)&&!removedEventIds.has(a.refId));markCampusEventHistory(c);
        const after=JSON.stringify({posts:c.posts.map(x=>x.id),comments:c.posts.flatMap(p=>p.comments.map(q=>q.id)),events:c.events.map(x=>[x.id,x.historyLocked]),regs:c.registrations.map(x=>x.id),notes:c.notifications.map(x=>x.id),actions:c.userActions.map(x=>x.id)});if(before!==after){saveCampusState(c);return true;}return false;
      }catch(e){console.warn("[蝴蝶小手机 v1.5.1] 正文校园同步失败",e);return false;}
    }

