    function ensureBaseContacts(st){
      st=st||getState();
      const name=getCharName();
      const list=Array.isArray(st.wechat.contacts)?st.wechat.contacts:[];
      let c=list.find(x=>String(x?.name||"")===String(name));
      if(!c){c={name,note:"当前角色",last:"",time:"",available:true,reason:""};list.unshift(c);}
      if(/联系人状态生成失败|暂不允许误发消息|生成失败/i.test(String(c.reason||""))){c.available=true;c.reason="";}
      // User avatars are preserved during contact discovery.
      st.wechat.contacts=list.slice(0,300);
      return st;
    }
    async function ensureContacts(force=false){
      let st=ensureBaseContacts(getState());
      saveState(st);
      const contactsScope=actionScope();
      if(features)await features.scanLore(false);
      if(contactsScope!==actionScope())return ensureBaseContacts(getState());
      st=ensureBaseContacts(getState());
      // Opening/browsing WeChat never calls AI. Contact discovery only runs after
      // the user explicitly presses the refresh button.
      if(!force)return st;
      if(!socialActionMoment("刷新微信联系人"))return st;
      const actionKey="refresh-contacts";
      if(!beginPhoneAction(actionKey))return st;
      const storySnapshot=socialStorySnapshot();
      const sys=`你在为一个沉浸式现代剧情手机补充【微信关键好友列表与当前可联系状态】。只允许使用当前主线正文、角色卡、世界书中已经出现或明确存在的关键人物，禁止为了凑列表凭空造陌生NPC。当前主线时间：【${storyTime()}】。当前主角姓名：【${getUserName()}】；当前角色：【${getCharName()}】。
判断人物此刻是否能使用微信：死亡、失联、昏迷、被隔绝通讯、剧情条件不允许时 available=false 并说明原因。只保留与当前user确有联系可能的关键人物；必须包含当前character，但绝不只限于character本人：正文或世界观中已经存在、与user有合理联系方式的关键NPC、家人、同事、朋友、对手等都可以进入通讯录并与user聊天。不要输出头像字段。
如果某联系人关系来自下面某段正文，source_message_indices必须列出对应绝对消息索引；只来自角色卡/世界书且不依赖近期正文时填空数组。
只输出JSON：{"contacts":[{"name":"姓名","note":"关系/备注（仅已知事实）","last":"已有聊天事实可概括；没有就空","time":"正文世界内最近联系时间；没有就空","available":true,"reason":"","source_message_indices":[绝对索引]}]}`;
      try{
        const obj=await askJson(sys,`根据当前剧情补充微信关键好友和状态。\n\n【近期正文（索引只能从这里选）】\n${socialStoryContext(18)}`);
        if(storySnapshot!==socialStorySnapshot()){pwin.alert?.("正文在联系人生成期间发生了变化，本次结果没有保存。请按当前正文再刷新一次。");return getState();}
        if(contactsScope!==actionScope())return getState();
        st=getState();
        const generated=Array.isArray(obj.contacts)?obj.contacts.slice(0,300):[];
        const oldMap=new Map(st.wechat.contacts.map(x=>[String(x.name),x]));
        const generatedNames=new Set();
        for(const x of generated){
          const name=String(x?.name||"").trim();if(!name)continue;
          generatedNames.add(name);
          const old=oldMap.get(name)||{};
          const storyLast=cleanGeneratedSocialText(x?.last||old.storyLast||old.last||"",160),rawContactTime=canonicalSocialMoment(x?.time||old.storyTime||""),contactMinute=parseWorldMinute(rawContactTime),nowMinute=parseWorldMinute(storyTime()),storyContactTime=contactMinute==null?"":(nowMinute!=null&&contactMinute>nowMinute?storyTime():rawContactTime);
          const thread=Array.isArray(st.wechat.threads[name])?st.wechat.threads[name]:[],latest=thread[thread.length-1];
          oldMap.set(name,{...old,name,note:String(x?.note||old.note||"").trim().slice(0,160),storyLast,storyTime:storyContactTime,last:latest?String(latest.text||"").slice(0,80):storyLast,time:latest?String(latest.time||""):storyContactTime,available:x?.available!==false,reason:String(x?.reason||"").trim().slice(0,180),_storyDiscovered:old._loreDiscovered?false:true,sourceStoryKeys:old._loreDiscovered?[]:socialSourceKeys(x?.source_message_indices)});
        }
        st.wechat.contacts=Array.from(oldMap.values()).filter(c=>{
          if(String(c?.name||"")===String(getCharName()))return true;
          if(c?._storyDiscovered!==true||generatedNames.has(String(c.name||"")))return true;
          return Array.isArray(st.wechat.threads[String(c.name||"")])&&st.wechat.threads[String(c.name||"")].length>0;
        }).slice(0,300);
        st=ensureBaseContacts(st);saveState(st);
      }catch(e){
        console.warn("[蝴蝶小手机 v1.5.1] 微信好友刷新遇到接口问题，保留现有联系人",e);
        if(contactsScope!==actionScope())return getState();
        st=ensureBaseContacts(getState());saveState(st);
      }finally{endPhoneAction(actionKey);}
      return st;
    }

    function syncContactPreview(st,name){
      const c=(st.wechat.contacts||[]).find(x=>String(x?.name||"")===String(name||""));if(!c)return;
      const arr=Array.isArray(st.wechat.threads?.[name])?st.wechat.threads[name]:[],last=arr[arr.length-1];
      c.last=last?String(last.text||"").replace(/\s+/g," ").slice(0,80):String(c.storyLast||"").slice(0,80);
      c.time=last?String(last.time||""):String(c.storyTime||"");
    }
    function contactActivityOrder(st,c){
      const arr=Array.isArray(st.wechat.threads?.[c?.name])?st.wechat.threads[c.name]:[],last=arr[arr.length-1];
      return last?socialRecordOrder(last):(parseWorldMinute(c?.time)||0)*60000;
    }

    async function renderWeChat(tab="chats"){
      setPhoneExpanded(true);
      view={app:"wechat",sub:tab,target:""};setTop("微信",true);updateClock();
      content.innerHTML=`${wechatTabs(tab)}<div class="loading">正在读取剧情里的微信……</div>`;bindWcTabs();
      const renderScope=actionScope();
      const st=await ensureContacts(false);
      if(renderScope!==actionScope()||view.app!=="wechat"||view.sub!==tab)return;
      if(tab==="me"){
        const menu=[
          ["💬","服务",false],["🧊","收藏",false],["🟢","朋友圈",true],["▶","视频号",false],
          ["🛍","小店与卡包",false],["🙂","表情",true],["⚙","设置",false]
        ];
        content.innerHTML=`${wechatTabs(tab)}<div class="wx-me"><div class="wx-me-profile">${avatarHtml(getUserName(),true)}<div style="min-width:0;flex:1"><div class="contact-name" style="font-size:.86em">${esc(getUserName())}</div><div class="tiny">微信号：${esc((getUserName()||"user").replace(/\s+/g,"").slice(0,18)||"user")}</div><div class="tiny">当前剧情时间：${esc(storyTime())}</div></div><div style="opacity:.45">›</div></div>${menu.map(([ic,tx,on])=>`<button class="wx-menu-row ${on?"functional":"decorative"}" type="button" ${on?`data-me-action="${tx==='表情'?'stickers':'moments'}"`:'disabled'}><span class="wx-menu-icon">${ic}</span><span class="wx-menu-text">${tx}</span><span class="wx-menu-arrow">›</span></button>`).join("")}</div>`;
        bindWcTabs();
        content.querySelector('[data-me-action="moments"]')?.addEventListener("click",()=>renderMoments(getState(),true));
        content.querySelector('[data-me-action="stickers"]')?.addEventListener("click",()=>features.stickersPage());
        const profile=content.querySelector(".wx-me-profile");if(profile){profile.title="点击修改头像";profile.addEventListener("click",()=>features.contactTools(getUserName(),()=>renderWeChat("me")));}
        return;
      }
      if(tab==="discover"){
        await renderMoments(st,false);return;
      }
      const allContacts=(st.wechat.contacts||[]).slice();
      const contacts=(tab==="chats"
        ?allContacts.filter(c=>String(c?.name||"")===String(getCharName())||(Array.isArray(st.wechat.threads?.[c?.name])&&st.wechat.threads[c.name].length>0)||String(c?.last||"").trim()).sort((a,b)=>contactActivityOrder(st,b)-contactActivityOrder(st,a))
        :allContacts.sort((a,b)=>String(a?.name||"")===String(getCharName())?-1:String(b?.name||"")===String(getCharName())?1:String(a?.name||"").localeCompare(String(b?.name||""),"zh-CN")));
      const html=contacts.length?contacts.map(c=>`<button class="contact ${c.available===false?"unavail":""}" data-contact="${esc(c.name)}" type="button">
        ${avatarHtml(c.name,false)}<div><div class="contact-name">${esc(c.name)}</div><div class="contact-last">${esc(c.available===false?(c.reason||"当前无法联系"):(c.last||c.note||""))}</div></div><div class="contact-time">${esc(c.time||"")}</div></button>`).join(""):`<div class="loading">当前剧情里没有可用微信联系人。</div>`;
      content.innerHTML=`${wechatTabs(tab)}<div class="wx-page-title">${tab==="contacts"?"通讯录 · 世界书与当前剧情":"聊天"}</div><div class="bf-actions"><button class="ph-secondary bf-people" type="button">世界书 / 头像</button><button class="ph-secondary bf-groups" type="button">群聊 · 由我建立</button></div><div class="wx-chat-list">${html}</div><button class="ph-secondary refresh-contacts" style="width:100%;margin-top:7px" type="button">按当前剧情刷新关键联系人</button>`;
      bindWcTabs();
      content.querySelectorAll("[data-contact]").forEach(b=>b.addEventListener("click",()=>openThread(b.dataset.contact)));
      content.querySelector(".bf-people")?.addEventListener("click",()=>features.peoplePage());
      content.querySelector(".bf-groups")?.addEventListener("click",()=>features.groupList());
      content.querySelector(".refresh-contacts")?.addEventListener("click",async()=>{content.querySelector(".refresh-contacts").textContent="刷新中…";await ensureContacts(true);renderWeChat(tab);});
    }

    async function refreshMoments(manual=true){
      const now=socialActionMoment("刷新朋友圈");if(!now)return false;
      const actionKey="refresh-moments";if(!beginPhoneAction(actionKey))return false;
      const storySnapshot=socialStorySnapshot();
      const sys=`生成一个仅与当前主线有关的微信【朋友圈】快照。当前时间：【${now}】。只允许使用正文、当前character角色卡、user/persona设定、世界观中已存在的关键人物/NPC，不得为了凑数量创造陌生NPC。人物若死亡、失联、无法使用手机，不得发新动态。只生成0-6条；没有依据可以空数组。每条只能是纯文字或emoji，绝对禁止图片、照片、[图片]、图片描述或媒体占位。不能替user发布、评论或点赞。内容和互动必须符合人物性格、身份、关系及其当前可知信息。若动态或评论来自某段正文，source_message_indices必须列出下面对应的绝对消息索引；只来自角色卡/世界书时填空数组。只输出JSON：{"moments":[{"author":"姓名","time":"正文世界内具体年月日时间","text":"纯文字/emoji动态","likes":["已存在人物姓名，最多4"],"source_message_indices":[绝对索引],"comments":[{"author":"姓名","text":"纯文字/emoji留言","time":"剧情时间","source_message_indices":[绝对索引]}]}]}`;
      try{
        const obj=await askJson(sys,`按当前剧情生成朋友圈。所有动态只能文字/emoji。\n\n【近期正文（索引只能从这里选）】\n${socialStoryContext(18)}`);
        if(storySnapshot!==socialStorySnapshot()){if(manual)pwin.alert?.("正文在朋友圈生成期间发生了变化，本次结果没有保存。请再刷新一次。");return false;}
        const st=getState(),protectedExisting=(st.wechat.moments||[]).filter(hasUserMomentInteraction),oldBySig=new Map(protectedExisting.map(p=>[socialPostSignature(p),p])),fresh=[];
        for(const row of (Array.isArray(obj?.moments)?obj.moments.slice(0,6):[])){
          const author=String(row?.author||"").trim().slice(0,100),text=cleanGeneratedSocialText(row?.text,1200);if(!author||!text||author===getUserName())continue;
          const postTime=safeSnapshotTime(row?.time,now),comments=[];
          for(const c of (Array.isArray(row?.comments)?row.comments.slice(0,8):[])){
            const ca=String(c?.author||"").trim().slice(0,100),ct=cleanGeneratedSocialText(c?.text,800);if(!ca||!ct||ca===getUserName())continue;
            comments.push({id:makeId("moment-comment"),author:ca,text:ct,time:safeSnapshotTime(c?.time,now,postTime),isUser:false,source:"generated",sourceStoryKeys:socialSourceKeys(c?.source_message_indices)});
          }
          const item={id:makeId("mom"),author,time:postTime,text,likes:socialStrings(row?.likes,4).filter(n=>n!==getUserName()),comments:dedupeSocialComments(comments,20),userLiked:false,userLikedAt:"",source:"generated",sourceStoryKeys:socialSourceKeys(row?.source_message_indices)};
          fresh.push(mergeSocialPost(item,oldBySig.get(socialPostSignature(item))));
        }
        const freshSigs=new Set(fresh.map(socialPostSignature)),preserved=protectedExisting.filter(p=>!freshSigs.has(socialPostSignature(p)));
        st.wechat.moments=dedupeMomentList([...preserved,...fresh]).slice(-30);saveState(st);return true;
      }catch(e){console.warn("[蝴蝶小手机 v1.5.1] 朋友圈刷新失败",e);if(manual)pwin.alert?.(friendlyGenError(e));return false;}
      finally{endPhoneAction(actionKey);}
    }

    async function renderMoments(st,fromMe=false){
      st=st||getState();
      const uname=getUserName();
      const cards=st.wechat.moments.length?st.wechat.moments.slice().sort((a,b)=>socialRecordOrder(b)-socialRecordOrder(a)).map(x=>{
        const likes=Array.isArray(x.likes)?x.likes:[],comments=Array.isArray(x.comments)?x.comments.slice(-12):[],liked=x.userLiked===true||likes.includes(uname),own=isUserMoment(x);
        const commentHtml=comments.map(c=>`<div class="wb-comment"><span>${c.replyTo?`<b>${esc(c.author||"")}</b> 回复 <b>@${esc(c.replyTo)}</b>：`:`<b>${esc(c.author||"")}：</b>`}${esc(c.text||"")} ${c.time?`<span class="wb-time">${esc(c.time)}</span>`:""}</span><button class="bubble-del moment-reply" data-momentreply="${esc(x.id||"")}" data-reply-author="${esc(c.author||"")}" data-reply-comment-id="${esc(c.id||"")}" type="button">回复</button>${isUserSocialComment(c)?`<button class="bubble-del moment-comment-del" data-moment-comment-del="${esc(c.id||"")}" data-moment-id="${esc(x.id||"")}" type="button">删除</button>`:""}</div>`).join("");
        return `<div class="wb-card" data-moment-card="${esc(x.id||"")}"><div class="author-line">${avatarHtml(x.author,own,"author-avatar")}<div style="min-width:0;flex:1"><span class="wb-author">${esc(x.author||"")}</span><span class="wb-time">${esc(x.time||"")}</span>${own?`<button class="bubble-del moment-audience-edit" type="button" data-id="${esc(x.id||'')}">${esc(visibilityLabel(x.visibility))}</button><button class="bubble-del moment-del" data-moment-del="${esc(x.id||"")}" style="float:right" type="button">删除</button>`:""}</div></div><div class="wb-text">${escLines(x.text||"")}</div><div class="wb-meta">♡ ${esc(likes.join("、")||"暂无点赞")}</div>${commentHtml}<div class="social-actions"><button class="moment-like ${liked?"active":""}" data-momentlike="${esc(x.id||"")}" type="button">${liked?"♥ 已赞":"♡ 点赞"}</button></div><div class="social-commenter"><input data-momentinput="${esc(x.id||"")}" placeholder="评论这条朋友圈…"><button data-momentcomment="${esc(x.id||"")}" type="button">发送</button></div></div>`;
      }).join(""):`<div class="loading">当前还没有朋友圈内容。打开页面不会自动调用AI；需要时请点下方刷新。</div>`;
      const back=fromMe?`<button class="ph-secondary moment-back-me" style="width:100%;margin-bottom:6px" type="button">‹ 返回“我”</button>`:"";
      content.innerHTML=`${wechatTabs(fromMe?"me":"discover")}${back}<div class="moment-compose"><div class="contact-name" style="margin-bottom:5px">${esc(uname)} · 发朋友圈</div><textarea class="moment-input" maxlength="500" placeholder="只能发表文字或 emoji…"></textarea><div class="tiny">仅文字 / emoji；不支持图片，也不会用文字假装描述图片。</div>${features.socials.audienceFields()}<button class="ph-primary moment-publish" style="width:100%;margin-top:6px" type="button">发表</button></div>${cards}<button class="ph-secondary refresh-moments" style="width:100%" type="button">按当前剧情刷新朋友圈</button>`;
      bindWcTabs();
      content.querySelector(".moment-back-me")?.addEventListener("click",()=>renderWeChat("me"));
      content.querySelectorAll(".moment-audience-edit").forEach(el=>el.addEventListener("click",()=>features.socials.audienceEditor(el.dataset.id,()=>renderMoments(getState(),fromMe))));
      content.querySelector(".moment-publish")?.addEventListener("click",()=>publishMoment(fromMe));
      content.querySelector(".refresh-moments")?.addEventListener("click",async e=>{const b=e.currentTarget;b.disabled=true;b.textContent="刷新中…";await refreshMoments(true);renderMoments(getState(),fromMe);});
      content.querySelectorAll("[data-momentlike]").forEach(b=>b.addEventListener("click",()=>toggleMomentLike(b.dataset.momentlike,fromMe)));
      content.querySelectorAll("[data-momentcomment]").forEach(b=>b.addEventListener("click",()=>commentMoment(b.dataset.momentcomment,fromMe)));
      content.querySelectorAll("[data-momentreply]").forEach(b=>b.addEventListener("click",()=>{const inp=Array.from(content.querySelectorAll("[data-momentinput]")).find(x=>x.dataset.momentinput===b.dataset.momentreply);if(inp){inp.dataset.replyTo=b.dataset.replyAuthor||"";inp.dataset.replyCommentId=b.dataset.replyCommentId||"";inp.placeholder=`回复 @${b.dataset.replyAuthor||""}…`;inp.focus();}}));
      content.querySelectorAll("[data-moment-del]").forEach(b=>b.addEventListener("click",()=>deleteMoment(b.dataset.momentDel,fromMe)));
      content.querySelectorAll("[data-moment-comment-del]").forEach(b=>b.addEventListener("click",()=>deleteMomentComment(b.dataset.momentId,b.dataset.momentCommentDel,fromMe)));
    }
    async function publishMoment(fromMe=false){
      const inp=content.querySelector(".moment-input"),txt=String(inp?.value||"").trim();if(!txt||!textOnlyInputOk(txt))return;
      const now=socialActionMoment("发表朋友圈");if(!now)return;
      const actionKey="publish-moment";if(!beginPhoneAction(actionKey))return;
      const visibility=features.socials.readAudience(content.querySelector(".moment-compose"));
      const id=makeId("moment-user"),storySnapshot=socialStorySnapshot(),st=getState();
      st.wechat.moments=Array.isArray(st.wechat.moments)?st.wechat.moments:[];
      st.wechat.moments.push({id,author:getUserName(),time:now,text:txt,visibility,likes:[],comments:[],userLiked:false,source:"user"});
      st.wechat.moments=st.wechat.moments.slice(-30);saveState(st);if(inp)inp.value="";
      await renderMoments(getState(),fromMe);
      const viewers=eligibleViewers(st.wechat.moments.find(p=>p.id===id),st.wechat.contacts,getUserName());
      if(!viewers.length){endPhoneAction(actionKey);return;}
      const sys=`【可见范围】只有以下人物能看到并参与此帖：${viewers.join("、")}。禁止其他人物点赞、评论或得知帖子内容。\n用户【${getUserName()}】刚在剧情朋友圈发表纯文字动态：“${txt}”。当前剧情时间：【${now}】。只根据当前正文、character角色卡、user/persona身份性格、世界观和已经存在的关键NPC，生成短时间内合理出现的点赞与评论。评论态度可以亲近、毒舌、夸赞、奉承、损友吐槽、阴阳怪气、质疑等，必须由既有关系和身份支撑，不要为了热闹制造陌生NPC。死亡、失联、无法上网或不可能看到这条朋友圈的人不得互动。所有互动只允许文字/emoji，禁止图片和图片描述。只输出JSON：{"likes":["会点赞的已存在人物，0-6"],"comments":[{"author":"已存在关键人物/NPC","text":"自然评论","time":"具体剧情时间"}]}`;
      try{
        const obj=await askJson(sys,`【user朋友圈】${getUserName()}：${txt}`);if(storySnapshot!==socialStorySnapshot())return;
        const s2=getState(),m=s2.wechat.moments.find(x=>x.id===id);
        if(m){m.likes=socialStrings(obj?.likes,6).filter(n=>viewers.includes(n)&&canViewMoment(m,n,getUserName()));m.comments=dedupeSocialComments((Array.isArray(obj?.comments)?obj.comments.slice(0,6):[]).map(c=>({id:makeId("moment-comment"),author:String(c?.author||"").trim().slice(0,100),text:cleanGeneratedSocialText(c?.text,800),time:safeReplyTime(c?.time,now),isUser:false,source:"generated"})).filter(c=>c.author&&c.text&&viewers.includes(c.author)&&canViewMoment(m,c.author,getUserName())),20);saveState(s2);}
      }catch(e){console.warn("[蝴蝶小手机 v1.5.1] 朋友圈已发表，但互动生成失败",e);}finally{endPhoneAction(actionKey);}
      if(view.app==="wechat")await renderMoments(getState(),fromMe);
    }

    function toggleMomentLike(id,fromMe=false){
      const st=getState(),m=st.wechat.moments.find(x=>String(x?.id||"")===String(id||""));if(!m)return;
      const uname=getUserName();m.likes=Array.isArray(m.likes)?m.likes:[];
      const i=m.likes.indexOf(uname),removing=i>=0||m.userLiked===true,now=removing?"":socialActionMoment("点赞朋友圈");if(!removing&&!now)return;
      if(removing){if(i>=0)m.likes.splice(i,1);m.userLiked=false;m.userLikedAt="";}else{m.likes.push(uname);m.userLiked=true;m.userLikedAt=now;}
      saveState(st);renderMoments(st,fromMe);
    }
    function deleteMoment(id,fromMe=false){
      const st=getState(),m=(st.wechat.moments||[]).find(x=>String(x?.id||"")===String(id||""));if(!m||!isUserMoment(m))return;
      st.wechat.moments=st.wechat.moments.filter(x=>String(x?.id||"")!==String(id||""));invalidatePhoneMemory();saveState(st);renderMoments(st,fromMe);
    }
    function deleteMomentComment(momentId,commentId,fromMe=false){
      const st=getState(),m=(st.wechat.moments||[]).find(x=>String(x?.id||"")===String(momentId||""));if(!m)return;
      const target=(m.comments||[]).find(c=>String(c?.id||"")===String(commentId||""));if(!target||!isUserSocialComment(target))return;
      const removed=new Set([String(commentId||"")]);let changed=true;while(changed){changed=false;for(const c of (m.comments||[])){if(c?.triggerRefId&&removed.has(String(c.triggerRefId))&&!removed.has(String(c.id||""))){removed.add(String(c.id||""));changed=true;}}}
      m.comments=(m.comments||[]).filter(c=>!removed.has(String(c?.id||"")));invalidatePhoneMemory();saveState(st);renderMoments(st,fromMe);
    }
    async function commentMoment(id,fromMe=false){
      const actionKey=`moment-comment:${id}`;
      if(!beginPhoneAction(actionKey))return;
      const input=Array.from(content.querySelectorAll("[data-momentinput]")).find(x=>String(x.dataset.momentinput||"")===String(id||""));const txt=String(input?.value||"").trim(),replyTo=String(input?.dataset?.replyTo||"").trim(),parentCommentId=String(input?.dataset?.replyCommentId||"").trim();
      if(!txt||!textOnlyInputOk(txt)){endPhoneAction(actionKey);return;}
      const now=socialActionMoment("评论朋友圈");if(!now){endPhoneAction(actionKey);return;}
      let st=getState(),m=st.wechat.moments.find(x=>String(x?.id||"")===String(id||""));
      if(!m){endPhoneAction(actionKey);return;}
      m.comments=Array.isArray(m.comments)?m.comments:[];
      const parentComment=(m.comments||[]).find(c=>String(c?.id||"")===parentCommentId),userCommentId=makeId("moment-user-comment"),storySnapshot=socialStorySnapshot();m.comments.push({id:userCommentId,author:getUserName(),text:txt,time:now,isUser:true,replyTo,triggerRefId:parentCommentId,source:"user",sourceStoryKeys:Array.isArray(parentComment?.sourceStoryKeys)?[...parentComment.sourceStoryKeys]:[]});m.comments=m.comments.slice(-20);saveState(st);
      const recentMomentComments=(m.comments||[]).slice(-8).map(c=>`${c.author||""}：${c.text||""}`).join("\n");
      if(input){input.value="";input.dataset.replyTo="";input.dataset.replyCommentId="";}
      // The user's comment is already canon. Show it immediately; AI follow-up can arrive later.
      await renderMoments(getState(),fromMe);
      const viewers=eligibleViewers(m,st.wechat.contacts,getUserName());
      const sys=`【可见范围】仅以下人物能知道本帖并回复：${viewers.join("、")||"无人"}。不得让范围外人物发言。\n用户【${getUserName()}】刚在朋友圈动态【${m.author||""}：${m.text||""}】下${replyTo?`回复@${replyTo}`:"评论"}：“${txt}”。当前剧情时间：【${now}】。
最近评论链：
${recentMomentComments||"暂无其他评论。"}
只根据角色卡、世界观、正文和已经存在的关键NPC，判断动态作者或确实会看到这条评论的关键人物是否自然回复。禁止凭空造陌生NPC。人物死亡/失联/无法上网时不得回复。可以无人回复。
若有人回复，必须是在回应user刚刚这句“${txt}”或紧邻评论链，不能突然聊正文里另一个无关话题。不要替user追加第二条评论。
只输出JSON：{"replies":[{"author":"动态作者或已存在关键NPC","text":"直接承接user当前评论的自然回复","time":"具体剧情时间"}]}，0-3条。`;
      try{
        const obj=await askJson(sys,`【朋友圈原动态】${m.author||""}：${m.text||""}\n【最近评论】\n${recentMomentComments||"无"}\n【user最新评论｜必须针对它】${txt}`);
        if(storySnapshot!==socialStorySnapshot())return;
        st=getState();m=st.wechat.moments.find(x=>String(x?.id||"")===String(id||""));
        if(m&&(m.comments||[]).some(c=>String(c?.id||"")===String(userCommentId))){m.comments=Array.isArray(m.comments)?m.comments:[];for(const r of (Array.isArray(obj?.replies)?obj.replies.slice(0,3):[])){const author=String(r?.author||"").trim(),text=cleanGeneratedSocialText(r?.text,800);if(author&&text&&author!==getUserName()&&viewers.includes(author)&&canViewMoment(m,author,getUserName()))m.comments.push({id:makeId("moment-reply"),author,text,time:safeReplyTime(r?.time,now),replyTo:getUserName(),triggerRefId:userCommentId,source:"generated"});}m.comments=dedupeSocialComments(m.comments,20);saveState(st);}
      }catch(e){console.warn("[蝴蝶小手机 v1.5.1] 朋友圈评论互动生成失败；user评论已保留",e);}
      finally{endPhoneAction(actionKey);}
      if(view.app==="wechat")await renderMoments(getState(),fromMe);
    }

    async function openThread(name){
      const threadScope=actionScope();
      const st=await ensureContacts(false);if(threadScope!==actionScope())return;
      const c=st.wechat.contacts.find(x=>x.name===name)||{name,available:true};
      view={app:"wechat",sub:"thread",target:name};setTop(name,true,()=>renderWeChat("chats"));updateClock();
      const arr=Array.isArray(st.wechat.threads[name])?st.wechat.threads[name]:[];
      const threadPending=arr.some(m=>m?.from==="user"&&m?.pending===true);
      const rows=arr.length?arr.map(m=>{
        const body=m.kind==="sticker"?features.stickerBody(m):m.kind==="image"?`<span class="tiny">旧版图片记录已隐藏</span>`:escLines(m.text||"");
        return `<div class="bubble-row ${m.from==="user"?"me":"them"}"><div class="bubble-line">${avatarHtml(m.from==="user"?getUserName():name,m.from==="user","chat-avatar")}<div><div class="bubble">${body}</div><div class="bubble-time">${esc(m.time||"")}${m.from==="user"?` <button class="bubble-del" type="button" data-msg="${esc(m.id||"")}">删除</button>${m.failed?` <button class="bubble-del" type="button" data-retry="${esc(m.pairId||m.id||"")}">重试回复</button>`:""}`:""}</div>${m.error?`<div class="tiny">${esc(m.error)}</div>`:""}</div></div></div>`;
      }).join(""):`<div class="loading">还没有聊天记录。</div>`;
      content.innerHTML=`<div class="bf-actions"><button class="ph-secondary bf-thread-profile" type="button">头像</button><button class="ph-secondary bf-thread-sticker" type="button" ${threadPending||c.available===false?"disabled":""}>表情包</button></div><div class="thread">${c.available===false?`<div class="warn tiny">${esc(c.reason||"当前无法联系")}</div>`:""}${rows}</div>
      <div class="composer"><textarea class="wx-input" placeholder="${c.available===false?"当前无法发送":(threadPending?"先等上一条回复/重试或删除后再发":"发消息…")}" ${(c.available===false||threadPending)?"disabled":""}></textarea><button class="send" type="button" ${(c.available===false||threadPending)?"disabled":""}>发送</button></div>`;
      content.querySelectorAll("[data-msg]").forEach(b=>b.addEventListener("click",()=>deleteWxPair(name,b.dataset.msg)));
      content.querySelectorAll("[data-retry]").forEach(b=>b.addEventListener("click",()=>retryWx(name,b.dataset.retry)));
      content.querySelector(".bf-thread-profile")?.addEventListener("click",()=>features.contactTools(name,()=>openThread(name)));
      content.querySelector(".bf-thread-sticker")?.addEventListener("click",()=>features.stickersPage(s=>sendWx(name,s),()=>openThread(name)));
      const inp=content.querySelector(".wx-input"),send=content.querySelector(".send");
      send?.addEventListener("click",()=>sendWx(name));
      inp?.addEventListener("keydown",e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();sendWx(name);}});
      content.scrollTop=content.scrollHeight;
    }
    
    function deleteWxPair(name,id){
      const st=getState(),arr=Array.isArray(st.wechat.threads[name])?st.wechat.threads[name]:[];
      const idx=arr.findIndex(x=>String(x?.id||"")===String(id||""));
      if(idx<0)return;
      // Delete the user's message and the immediately linked NPC reply if same pairId
      const pair=arr[idx]?.pairId||arr[idx]?.id;
      st.wechat.threads[name]=arr.filter(x=>(x?.pairId||x?.id)!==pair);
      syncContactPreview(st,name);
      invalidatePhoneMemory();
      saveState(st);openThread(name);
    }
    
    function parseWorldMinute(v){
      const s=String(v||"");
      let m=s.match(/((?:18|19|20|21)\d{2})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日(?:[\s\S]*?(\d{1,2})\s*[:：]\s*(\d{2}))?/);
      if(!m)m=s.match(/((?:18|19|20|21)\d{2})[-/.](\d{1,2})[-/.](\d{1,2})(?:[ T](\d{1,2})[:：](\d{2}))?/);
      if(!m)return null;
      const y=+m[1],mo=+m[2],d=+m[3],h=m[4]==null?0:+m[4],mi=m[5]==null?0:+m[5];
      if(!Number.isFinite(y+mo+d+h+mi)||mo<1||mo>12||d<1||d>31||h<0||h>23||mi<0||mi>59)return null;
      const dt=new Date(Date.UTC(y,mo-1,d,h,mi));
      if(dt.getUTCFullYear()!==y||dt.getUTCMonth()!==mo-1||dt.getUTCDate()!==d)return null;
      return dt.getTime()/60000;
    }
    function canonicalSocialMoment(value){
      const day=concreteDateFromText(value);if(!day)return "";return formatConcreteMoment(day,timelineClock(value));
    }
    function safeReplyTime(candidate,sentTime){
      const raw=String(candidate||"").trim(),s=canonicalSocialMoment(sentTime)||String(sentTime||"").trim(),c=canonicalSocialMoment(raw);
      if(!c||/(?:第\s*\d+\s*天|\d+\s*天后|次日|翌日|第二天|隔天|一周后|下周)/.test(raw))return s||"正文公历日期待补全";
      const cm=parseWorldMinute(c),sm=parseWorldMinute(s),nowLabel=storyTime(),now=parseWorldMinute(nowLabel);
      if(sm!=null&&(cm==null||cm<sm))return s||"正文公历日期待补全";
      if(now!=null&&cm!=null&&cm>now)return nowLabel||s||"正文公历日期待补全";
      return c||s||"正文公历日期待补全";
    }
    function safeSnapshotTime(candidate,currentLabel,floorLabel=""){
      const raw=String(candidate||"").trim(),nowLabel=canonicalSocialMoment(currentLabel)||String(currentLabel||storyTime()).trim(),floor=canonicalSocialMoment(floorLabel)||String(floorLabel||"").trim(),c=canonicalSocialMoment(raw);
      if(!c||/(?:第\s*\d+\s*天|\d+\s*天后|次日|翌日|第二天|隔天|一周后|下周)/.test(raw))return floor||nowLabel||"正文公历日期待补全";
      const cm=parseWorldMinute(c),nm=parseWorldMinute(nowLabel),fm=parseWorldMinute(floor);
      if(cm==null)return floor||nowLabel||"正文公历日期待补全";
      if(nm!=null&&cm>nm)return nowLabel;
      if(fm!=null&&cm<fm)return floor;
      return c;
    }

    async function generateWxReply(name,pair,txt,now){
      const replyScope=actionScope(),replyStory=socialStorySnapshot();
      const s0=getState(),oldArr=Array.isArray(s0.wechat.threads[name])?s0.wechat.threads[name]:[];
      const recentThread=oldArr.slice(-12).map((m,i)=>{
        const who=m?.from==="user"?getUserName():name;
        return `${i+1}. ${m?.time||""} ${who}：${String(m?.text||"").slice(0,500)}`;
      }).join("\n");
      const phoneLongMemory=getPhoneMemory().summary||"";
      const sys=`你正在生成现代剧情里的微信回复。发送者是用户【${getUserName()}】，收件人是已建立人物【${name}】。当前主线时间：【${now}】。严格继承character角色卡、user/persona、世界观、正文、这个联系人过去的微信记录、该NPC已知信息和通讯条件。如果此人此刻死亡、失联、昏迷、被隔绝通讯或剧情原因不能回复，available=false，不得硬让他上线。若可回复，长度完全按人物习惯与最新消息决定，可以一个字、一句或多条。必须直接回应user最新这条微信，不要跳去回答正文里别的话题，也不要替user补下一步。\n【媒体规则】允许文字、emoji和用户已导入的真实表情包。不得用[图片]等占位假装发送媒体。可以在JSON中附加sticker_id字段，ID只能取自表情库；含义通过名称传递，不声称看过真实图像。表情库：${JSON.stringify(features?.stickerCatalog()||[])}。\n【最近微信线程】\n${recentThread||"此前没有微信聊天。"}\n【手机长期记忆】\n${phoneLongMemory||"暂无。"}\n【本轮最新微信】\n${getUserName()}：<<<${txt}>>>\n只输出JSON：{"available":true,"reason":"","reply":"直接回应最新微信的纯文字/emoji回复；可用换行分成多条","reply_time":"正文世界内具体YYYY年MM月DD日 HH:mm"}。`;
      const obj=await askJson(sys,`【当前微信线程】\n${recentThread||"无历史"}\n\n【最新user消息】\n${getUserName()}：${txt}`);
      if(replyScope!==actionScope())return;
      if(replyStory!==socialStorySnapshot())throw new Error("剧情在回复期间变化，请重试");
      const s2=ensureBaseContacts(getState()),a2=Array.isArray(s2.wechat.threads[name])?s2.wechat.threads[name]:[];
      const userMsg=a2.find(x=>(x?.pairId||x?.id)===pair&&x?.from==="user");
      // The user may delete the pending message while generation is running.
      // In that case the late reply must be discarded instead of resurrecting the pair.
      if(!userMsg)return;
      userMsg.pending=false;userMsg.failed=false;userMsg.error="";
      if(obj?.available===false){
        const cc=s2.wechat.contacts.find(x=>x.name===name);if(cc){cc.available=false;cc.reason=String(obj.reason||"当前无法联系");}
      }else{
        let reply=cleanGeneratedSocialText(obj?.reply,3000);
        reply=reply.replace(/[\[【]\s*(?:图片|照片|语音|视频|文件)\s*[：:][\s\S]*?[\]】]/g,"").replace(/(?:发来|发了|传来|传了).{0,8}(?:图片|照片|语音|视频|文件)/g,"").trim();
        a2.splice(0,a2.length,...a2.filter(x=>!((x?.pairId||x?.id)===pair&&x?.from==="npc")));
        const rt=safeReplyTime(obj?.reply_time,now);
        if(reply)a2.push({id:makeId("wxr"),pairId:pair,from:"npc",text:reply,time:rt,kind:"text"});
        const sticker=s2.stickers.find(s=>s.id===obj?.sticker_id);if(sticker)a2.push({id:makeId("wxr"),pairId:pair,from:"npc",text:sticker.name,stickerId:sticker.id,time:rt,kind:"sticker"});
        const cc=s2.wechat.contacts.find(x=>x.name===name);if(cc){cc.available=true;cc.reason="";cc.last=String(reply||txt).split(/\n/)[0].slice(0,40);cc.time=rt;}
      }
      s2.wechat.threads[name]=a2.slice(-60);syncContactPreview(s2,name);saveState(s2);
    }

    async function markWxPending(name,pair,error){
      const s2=ensureBaseContacts(getState()),a2=Array.isArray(s2.wechat.threads[name])?s2.wechat.threads[name]:[];
      const u=a2.find(x=>(x?.pairId||x?.id)===pair&&x?.from==="user");if(u){u.pending=false;u.failed=true;u.error=friendlyGenError(error);}
      s2.wechat.threads[name]=a2;syncContactPreview(s2,name);saveState(s2);
    }
    async function retryWx(name,pair){
      const st=getState(),arr=Array.isArray(st.wechat.threads[name])?st.wechat.threads[name]:[];
      const u=arr.find(x=>(x?.pairId||x?.id)===pair&&x?.from==="user");if(!u)return;
      if(u.pending)return;
      const retryTime=socialActionMoment("重试微信回复");if(!retryTime)return;
      const retryScope=actionScope();
      u.pending=true;u.failed=false;u.error="正在重试回复……";saveState(st);openThread(name);
      try{await generateWxReply(name,pair,String(u.text||""),retryTime);}catch(e){console.warn("[蝴蝶小手机 v1.5.1] 微信重试失败",e);if(retryScope===actionScope())await markWxPending(name,pair,e);}if(retryScope===actionScope()&&view.app==="wechat"&&view.target===name)openThread(name);
    }
    async function sendWx(name,sticker=null){
      const sendScope=actionScope();
      const inp=content.querySelector(".wx-input"),send=content.querySelector(".send");
      const txt=sticker?String(sticker.name):String(inp?.value||"").trim();if(!txt||(!sticker&&!textOnlyInputOk(txt)))return;
      const now=socialActionMoment("发送微信");if(!now)return;
      const st=await ensureContacts(false),c=st.wechat.contacts.find(x=>x.name===name);
      if(sendScope!==actionScope())return;
      if(c&&c.available===false)return;
      if((st.wechat.threads[name]||[]).some(m=>m?.from==="user"&&m?.pending))return;
      if(sticker&&!st.stickers.some(s=>s.id===sticker.id))return;
      if(send)send.disabled=true;if(inp)inp.disabled=true;
      const pair=makeId("wxpair");
      const arr=Array.isArray(st.wechat.threads[name])?st.wechat.threads[name]:[];
      arr.push({id:makeId("wxu"),pairId:pair,from:"user",text:txt,time:now,kind:sticker?"sticker":"text",stickerId:sticker?.id||"",pending:true,failed:false,error:"正在等待回复……"});
      st.wechat.threads[name]=arr;syncContactPreview(st,name);saveState(st);openThread(name);
      try{await generateWxReply(name,pair,txt,now);}catch(e){console.warn("[蝴蝶小手机 v1.5.1] 微信回复遇到接口问题，消息已保留",e);if(sendScope===actionScope())await markWxPending(name,pair,e);}if(sendScope===actionScope()&&view.app==="wechat"&&view.sub==="thread"&&view.target===name)openThread(name);
    }

