    async function refreshWeibo(){
      const now=socialActionMoment("刷新微博与热搜");if(!now)return getState();
      const actionKey="refresh-weibo";
      if(!beginPhoneAction(actionKey))return getState();
      const storySnapshot=socialStorySnapshot();
      const mem=getStoryMemory();
      const sys=`你在为沉浸式现代剧情生成【微博快照】。当前主线时间：【${now}】；当前事件：【${mem.event||""}】；最近剧情摘要：【${mem.summary||""}】。当前character：【${getCharName()}】；当前user/persona：【${getUserName()}】。
只能使用当前正文、角色卡、世界书中已经发生/存在的事情与关键人物。禁止随机生成与主线无关的真实世界新闻、明星八卦、社会热点或陌生NPC。热搜只允许收录“在当前主线时间往前7个世界日内发生”的正文相关公共事件；超过7天必须不进active_hot。没有公共事件就空数组。
微博动态可包含关键人物公开发帖、合理的粉丝/路人/黑粉/脱粉回踩评论，但只有在人物/事件确实具有公众曝光度时才能出现大规模互动。普通人不要凭空百万点赞。死去/失联/无法使用网络的人不能发新动态、评论或点赞。
评论不必全是好话，可以支持、质疑、嘲讽、恶评、黑粉、脱粉回踩等混合反应，但必须由剧情原因支撑。全部只允许文字/emoji，禁止图片、照片、媒体占位或图片描述。不能替user发微博、评论或点赞。
若动态、评论或热搜来自某段正文，source_message_indices必须列出下面对应的绝对消息索引；只来自角色卡/世界书时填空数组。
只输出JSON：
{"feed":[{"author":"已存在人物或合理匿名公共账号","time":"具体年月日时间","kind":"post或article","title":"仅article时填写文章标题，否则空字符串","text":"与正文有关的纯文字内容","likes":123,"source_message_indices":[绝对索引],"comments":[{"author":"关键NPC或匿名网友","text":"留言","time":"具体剧情时间","source_message_indices":[绝对索引]}]}],
"active_hot":[{"rank":1,"tag":"热搜词条","heat":"与人物规模匹配的热度","event_time":"事件发生时间","source_message_indices":[绝对索引]}]}
每组0-8条，宁缺毋滥。`;
      try{
        const obj=await askJson(sys,`按当前剧情刷新微博首页和近7天热搜。\n\n【近期正文（索引只能从这里选）】\n${socialStoryContext(20)}`);
        if(storySnapshot!==socialStorySnapshot()){pwin.alert?.("正文在微博生成期间发生了变化，本次结果没有保存。请再刷新一次。");return getState();}
        const st=getState(),protectedExisting=(st.weibo.feed||[]).filter(hasUserWeiboInteraction),oldBySig=new Map(protectedExisting.map(p=>[socialPostSignature(p),p])),freshFeed=[];
        for(const row of (Array.isArray(obj?.feed)?obj.feed.slice(0,8):[])){
          const author=String(row?.author||"").trim().slice(0,100),text=cleanGeneratedSocialText(row?.text,3000);if(!author||!text||author===getUserName())continue;
          const postTime=safeSnapshotTime(row?.time,now),comments=[];
          for(const c of (Array.isArray(row?.comments)?row.comments.slice(0,12):[])){
            const ca=String(c?.author||"").trim().slice(0,100),ct=cleanGeneratedSocialText(c?.text,1000);if(!ca||!ct||ca===getUserName())continue;
            comments.push({id:makeId("wb-comment"),author:ca,text:ct,time:safeSnapshotTime(c?.time,now,postTime),isUser:false,source:"generated",sourceStoryKeys:socialSourceKeys(c?.source_message_indices)});
          }
          const item={id:makeId("wbf"),author,time:postTime,kind:row?.kind==="article"?"article":"post",title:row?.kind==="article"?String(row?.title||"").trim().slice(0,120):"",text,likes:Math.min(9999999,Math.max(0,Math.round(Number(row?.likes)||0))),comments:dedupeSocialComments(comments,20),userLiked:false,userLikedAt:"",source:"generated",sourceStoryKeys:socialSourceKeys(row?.source_message_indices)};
          freshFeed.push(mergeSocialPost(item,oldBySig.get(socialPostSignature(item))));
        }
        const freshSigs=new Set(freshFeed.map(socialPostSignature)),preserved=protectedExisting.filter(p=>!freshSigs.has(socialPostSignature(p)));
        st.weibo.feed=[...preserved,...freshFeed].slice(-20);
        const stillValid=filterHotSevenDays(st.weibo.hot);
        const fresh=filterHotSevenDays((Array.isArray(obj.active_hot)?obj.active_hot:[]).map(x=>({id:makeId("wbhot"),rank:0,tag:cleanGeneratedSocialText(x?.tag,120),heat:String(x?.heat||"").slice(0,80),event_time:canonicalSocialMoment(x?.event_time),source:"generated",sourceStoryKeys:socialSourceKeys(x?.source_message_indices)})).filter(x=>x.tag&&x.event_time));
        const byTag=new Map();
        for(const x of stillValid){const k=String(x?.tag||"").trim();if(k)byTag.set(k,x);}
        for(const x of fresh){const k=String(x?.tag||"").trim();if(k)byTag.set(k,x);}
        st.weibo.hot=Array.from(byTag.values())
          .sort((a,b)=>(parseWorldMinute(b?.event_time)||0)-(parseWorldMinute(a?.event_time)||0))
          .slice(0,12)
          .map((x,i)=>({...x,rank:i+1}));
        st.weibo.lastRefresh=now;saveState(st);return st;
      }catch(e){console.warn("[蝴蝶小手机 v1.5.1] 微博刷新失败",e);pwin.alert?.(friendlyGenError(e));return getState();}
      finally{endPhoneAction(actionKey);}
    }
    function wbCard(x,own=false){
      const comments=Array.isArray(x?.comments)?x.comments.slice(-12):[];
      const isUser=own||String(x?.author||"")===String(getUserName());
      const shownLikes=Math.max(0,Number(x?.likes)||0)+(x?.userLiked?1:0);
      const isArticle=x?.kind==="article";
      const commentHtml=comments.map(c=>`<div class="wb-comment"><span>${c.replyTo?`<b>${esc(c.author||"")}</b> 回复 <b>@${esc(c.replyTo)}</b>：`:`<b>${esc(c.author||"")}：</b>`}${esc(c.text||"")} ${c.time?`<span class="wb-time">${esc(c.time)}</span>`:""}</span><button class="bubble-del wb-reply" data-wbreply="${esc(x.id||"")}" data-reply-author="${esc(c.author||"")}" data-reply-comment-id="${esc(c.id||"")}" type="button">回复</button>${isUserSocialComment(c)?`<button class="bubble-del wb-comment-del" data-wb-comment-del="${esc(c.id||"")}" data-wb-id="${esc(x.id||"")}" type="button">删除</button>`:""}</div>`).join("");
      return `<div class="wb-card" data-wbcard="${esc(x.id||"")}"><div class="author-line">${avatarHtml(x.author||getUserName(),isUser,"author-avatar")}<div style="min-width:0;flex:1"><span class="wb-author">${esc(x.author||"")}</span><span class="wb-time">${esc(x.time||"")}</span>${own?`<button class="bubble-del wb-del" data-wbdel="${esc(x.id||"")}" style="float:right" type="button">删除</button>`:""}</div></div>${isArticle?`<div class="wb-article-title">📄 ${esc(x.title||"文章")}</div>`:""}<div class="wb-text">${escLines(x.text||"")}</div><div class="wb-meta">${isArticle?"文章 · ":""}♡ ${esc(shownLikes)} · 评论 ${comments.length}</div>${commentHtml}<div class="social-actions"><button class="wb-like ${x?.userLiked?"active":""}" data-wblike="${esc(x.id||"")}" type="button">${x?.userLiked?"♥ 已赞":"♡ 点赞"}</button></div><div class="social-commenter"><input data-wbinput="${esc(x.id||"")}" placeholder="评论这条${isArticle?"文章":"微博"}…"><button data-wbcomment="${esc(x.id||"")}" type="button">发送</button></div></div>`;
    }

    
    function findWeiboPost(st,id){
      for(const key of ["feed","myPosts"]){const p=(st.weibo[key]||[]).find(x=>String(x?.id||"")===String(id||""));if(p)return {post:p,key};}
      return null;
    }
