      content.querySelectorAll("[data-wblike]").forEach(b=>b.addEventListener("click",()=>toggleWeiboLike(b.dataset.wblike)));
      content.querySelectorAll("[data-wbcomment]").forEach(b=>b.addEventListener("click",()=>commentWeibo(b.dataset.wbcomment)));
      content.querySelectorAll("[data-wbreply]").forEach(b=>b.addEventListener("click",()=>{const inp=Array.from(content.querySelectorAll("[data-wbinput]")).find(x=>x.dataset.wbinput===b.dataset.wbreply);if(inp){inp.dataset.replyTo=b.dataset.replyAuthor||"";inp.dataset.replyCommentId=b.dataset.replyCommentId||"";inp.placeholder=`回复 @${b.dataset.replyAuthor||""}…`;inp.focus();}}));
